exports.semantic_css:
:root {
  --color-background: var(--color-slate-50);
  --color-surface: #ffffff;
  --color-text: var(--color-slate-900);
  --color-text-muted: var(--color-slate-600);
  --color-border: var(--color-slate-200);
  --color-border-strong: var(--color-slate-500);
  --color-primary: var(--color-indigo-600);
  --color-primary-hover: var(--color-indigo-700);
  --color-on-primary: #ffffff;
  --color-success: var(--color-emerald-700);
  --color-warning: var(--color-amber-700);
  --color-danger: var(--color-rose-600);
  --color-info: var(--color-sky-700);
  --color-success-subtle: var(--color-emerald-50);
  --color-warning-subtle: var(--color-amber-50);
  --color-danger-subtle: var(--color-rose-50);
  --color-info-subtle: var(--color-sky-50);
}
@media (prefers-color-scheme: dark) {
  :root {
    --color-background: var(--color-slate-950);
    --color-surface: var(--color-slate-900);
    --color-text: var(--color-slate-50);
    --color-text-muted: var(--color-slate-300);
    --color-border: var(--color-slate-800);
    --color-border-strong: var(--color-slate-500);
    --color-primary: var(--color-indigo-300);
    --color-primary-hover: var(--color-indigo-200);
    --color-on-primary: var(--color-slate-950);
    --color-success: var(--color-emerald-300);
    --color-warning: var(--color-amber-300);
    --color-danger: var(--color-rose-300);
    --color-info: var(--color-sky-300);
    --color-success-subtle: var(--color-emerald-950);
    --color-warning-subtle: var(--color-amber-950);
    --color-danger-subtle: var(--color-rose-950);
    --color-info-subtle: var(--color-sky-950);
  }
}
